-- PT114-S1-Q3. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT114-S1-Q3$batch10$ AND q.stimulus=$batch10$An anthropologist hypothesized that a certain medicinal powder contained a significant amount of the deadly toxin T. When the test she performed for the presence of toxin T was negative, the anthropologist did not report the results. A chemist who nevertheless learned about the test results charged the anthropologist with fraud. The anthropologist, however, countered that those results were invalid because the powder had inadvertently been tested in an acidic solution.$batch10$ AND q.prompt=$batch10$In the absence of the anthropologist's reply, which one of the following principles, if established, would most support the chemist's charge?$batch10$ AND q.correct_choice=$batch10$E$batch10$) THEN RAISE EXCEPTION 'Question changed: PT114-S1-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT114-S1-Q3$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S1-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT114-S1-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$The chemist charges the anthropologist with fraud.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The anthropologist's hypothesis was that the powder contained toxin T. The test came back negative, and the anthropologist didn't report it.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$Set the reply aside, as the stem says. All we have is a scientist who failed to report a result that went against the hypothesis. The principle has to make that failure fraud.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Scientists who fail to report a disconfirming result commit fraud.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT114-S1-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$Both cases here involve reporting something. The anthropologist reported nothing, so neither kind of fraud fits.$batch10$), ($batch10$B$batch10$, $batch10$This says fraud is possible even when some disconfirmations are reported. It doesn't say that failing to report one is fraud.$batch10$), ($batch10$C$batch10$, $batch10$This says a scientist can leave out disconfirmations and still be innocent. That helps the anthropologist, not the chemist.$batch10$), ($batch10$D$batch10$, $batch10$This is about reporting a result one knows is invalid. The anthropologist reported nothing.$batch10$), ($batch10$E$batch10$, $batch10$The anthropologist left out a test that could be read as disconfirming the hypothesis. This principle says that is fraud, so it supports the charge.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT114-S1-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
